from base.service import BaseServicefrom entities import Container, ContainerTypefrom helpers.search import Paginationfrom repositories.container import ContainerRepositoryfrom schemas.container import ContainerUpdatefrom sqlalchemy.ext.asyncio import AsyncSessionfrom utils.container import ContainerSearchParamsclass ContainerService(BaseService[Container, ContainerRepository]):    def __init__(self, session: AsyncSession):        super().__init__(Container, session, ContainerRepository)    async def search_container(            self, type_: ContainerType,            search: ContainerSearchParams,            pagination: Pagination    ) -> list[Container]:        containers = await self.repository.search(            type_=type_, **pagination.dict(), **search.dict()        )        return containers    async def update_container(self, container_id: int, update: ContainerUpdate):        await self.update_item(container_id, **update.model_dump(exclude_none=True))